import 'dart:io';

import 'package:dart_frog/dart_frog.dart';
import 'package:maktub_backend/features/acceso/club_context/club_context.dart';
import 'package:maktub_backend/infraestructura/http.dart';
import 'package:maktub_core/maktub_core.dart';
import 'package:mongo_dart/mongo_dart.dart';

import 'record_block_time_store.dart';

/// `PUT /clubes/{clubId}/sesiones/{sesionId}/tiempos/{tiempoId}` body `{bloque, bloqueNombre, modoAtletas?,
/// atletaIds, inicio, fin, interrumpido?}` → 200 with the stored `BlockTime`. Needs [Accion.registrar].
///
/// [timeId] is generated by the client, so repeating the write (the retry queue does) leaves one document, and
/// doing the same block twice uses two ids and leaves two times. The seconds are not sent: they come from `inicio`
/// and `fin` (ISO 8601). `modoAtletas` (`simultaneo` / `por_turnos`) is left out for a block without sets. Block
/// times are not published over the live channel.
///
/// A coach writes for any present athletes, and an athlete present in the session for any present athletes (in a
/// personal club, only for themselves), the same rule as recording a set. 400 if the body is malformed (including
/// `fin` before `inicio`), 403 if the user cannot write it, 404 if the session is not in the club, 422 if an
/// athlete is not present. [store] and [now] are for tests.
Future<Response> recordBlockTimeEndpoint(
  RequestContext context,
  String sessionId,
  String timeId, {
  RecordBlockTimeStore? store,
  DateTime Function()? now,
}) async {
  final club = context.read<ClubContext>().authorize(Accion.registrar);
  final body = await leerCuerpoJson(context.request);
  final time = await RecordBlockTime(
    store ?? MongoRecordBlockTimeStore(context.read<Db>()),
    now: now,
  )(club, sessionId, timeId, body);
  return Response.json(body: time.toJson());
}

class RecordBlockTime {
  RecordBlockTime(this._store, {DateTime Function()? now})
    : _now = now ?? DateTime.now;

  final RecordBlockTimeStore _store;
  final DateTime Function() _now;

  Future<BlockTime> call(
    ClubContext club,
    String sessionId,
    String timeId,
    Json body,
  ) async {
    final id = _parseId(timeId);
    final input = _Input.fromBody(body);
    final session = await _store.session(club.clubId, sessionId);
    if (session == null) {
      throw const ErrorDeSolicitud.noEncontrado('Sesión no encontrada.');
    }
    final present = session.presentAthleteIds;
    if (!input.athleteIds.every(present.contains)) {
      throw ErrorDeSolicitud(
        'Un atleta no está presente en la sesión.',
        estado: HttpStatus.unprocessableEntity,
      );
    }
    if (!club.can(Accion.planificar)) {
      final own = await _store.athleteIdOfUser(club.clubId, club.userId);
      final allowed =
          own != null &&
          present.contains(own) &&
          (club.clubType != TipoClub.personal ||
              input.athleteIds.every((a) => a == own));
      if (!allowed) throw forbiddenRole;
    }
    final now = _now();
    return _store.upsert(
      BlockTime(
        id: id,
        clubId: club.clubId,
        sessionId: session.id,
        blockIndex: input.blockIndex,
        blockName: input.blockName,
        athleteMode: input.athleteMode,
        athleteIds: input.athleteIds,
        start: input.start,
        end: input.end,
        interrupted: input.interrupted,
        auditoria: Auditoria.nueva(
          club.userId,
          ahora: now,
        ).modificada(club.userId, ahora: now),
      ),
    );
  }
}

String _parseId(String value) {
  if (!RegExp(r'^[A-Za-z0-9_-]{1,64}$').hasMatch(value)) {
    throw const ErrorDeSolicitud('El id del tiempo no es válido.');
  }
  return value;
}

class _Input {
  _Input({
    required this.blockIndex,
    required this.blockName,
    required this.athleteMode,
    required this.athleteIds,
    required this.start,
    required this.end,
    required this.interrupted,
  });

  factory _Input.fromBody(Json body) {
    final index = body['bloque'];
    if (index is! num || index != index.roundToDouble() || index < 0) {
      throw const ErrorDeSolicitud('"bloque" debe ser un entero desde 0.');
    }
    final name = body['bloqueNombre'];
    if (name is! String || name.length > 200) {
      throw const ErrorDeSolicitud('"bloqueNombre" debe ser texto.');
    }
    final modeValue = body['modoAtletas'];
    final AthleteMode? mode;
    try {
      mode = modeValue == null ? null : AthleteMode.deCable(modeValue);
    } on Object {
      throw const ErrorDeSolicitud('"modoAtletas" no es válido.');
    }
    final athletes = body['atletaIds'];
    if (athletes is! List ||
        athletes.isEmpty ||
        athletes.any((a) => a is! String || a.trim().isEmpty)) {
      throw const ErrorDeSolicitud(
        '"atletaIds" debe ser una lista de ids, al menos uno.',
      );
    }
    final start = _instant(body['inicio'], 'inicio');
    final end = _instant(body['fin'], 'fin');
    if (end.isBefore(start)) {
      throw const ErrorDeSolicitud('"fin" no puede ser anterior a "inicio".');
    }
    final interrupted = body['interrumpido'];
    if (interrupted != null && interrupted is! bool) {
      throw const ErrorDeSolicitud(
        '"interrumpido" debe ser verdadero o falso.',
      );
    }
    return _Input(
      blockIndex: index.toInt(),
      blockName: name.trim(),
      athleteMode: mode,
      athleteIds: [
        for (final a in {...athletes.cast<String>()}) a,
      ],
      start: start,
      end: end,
      interrupted: interrupted == true,
    );
  }

  final int blockIndex;
  final String blockName;
  final AthleteMode? athleteMode;
  final List<String> athleteIds;
  final DateTime start;
  final DateTime end;
  final bool interrupted;
}

DateTime _instant(Object? value, String field) {
  final parsed = value is String ? DateTime.tryParse(value) : null;
  if (parsed == null) {
    throw ErrorDeSolicitud('"$field" debe ser un instante ISO 8601.');
  }
  return parsed.toUtc();
}
